import * as THREE from 'three';
import { matte, PALETTE } from './primitives.js';

// Movement 195: Brown's face wheels carry plain rectangular slots, open at
// the rim, and one worm between them drives both. A worm whose crest is cut
// to fit straight slots is exact: the crest is generated by the slots
// themselves (scripts/generate-worm-crest-195.mjs sweeps both wheels' slot
// walls, grown by the running clearance, through a worm turn and keeps the
// crest below them). The worm's axis stands clear of both wheel faces, so
// only the outer part of its square thread dips into the slots; the root
// and the rest of the thread never reach the lands.

export const FACE_SLOT_WORM_195 = Object.freeze({
  teeth: 24,
  // Distance from each wheel's axis to the worm axis (the pitch radius).
  wormAxisRadius: 1.12,
  wheelOuterRadius: 1.22,
  wheelDepth: 0.36,
  boreRadius: 0.074,
  // The wheel faces stand this far behind / in front of the worm axis.
  faceOffset: 0.311,
  slotWidth: 0.1,
  slotInnerRadius: 0.995,
  slotDepth: 0.06,
  wormTipRadius: 0.33,
  wormRootRadius: 0.16,
  wormBoreRadius: 0.081,
  wormShaftRadius: 0.08,
  threadWidth: 0.078,
  // Left-handed, so the visible front of each thread leans as Brown draws it.
  handedness: -1,
  wormTurns: 3.5,
  clearance: 0.0025,
  // Extra cut so the crest's straight chords between samples keep the
  // clearance past the slots' sharp corners.
  crestAllowance: 0.001,
  // Render / bake grid over the thread crest: u across the thread, theta
  // along the helix.
  crestSteps: 24,
  rootSteps: 8,
  angularSteps: 256,
});

const TAU = Math.PI * 2;

export function faceSlotWorm195Pitch(p = FACE_SLOT_WORM_195) {
  return TAU * p.wormAxisRadius / p.teeth;
}

// One wheel, local frame: the slotted face at z = 0, the body behind it to
// z = -depth, 24 slots centred on the local angles k * 2 pi / 24. One closed
// solid: flat face, flat slot floors and walls, a true cylindrical rim and
// a through bore.
export function pocketFaceWheel195Geometry(p = FACE_SLOT_WORM_195) {
  const { teeth, wheelOuterRadius: R, wheelDepth: T, boreRadius: B, slotWidth: s, slotInnerRadius: rin, slotDepth: D } = p;
  const pitchAngle = TAU / teeth, half = s / 2;
  const mouthHalfAngle = Math.asin(half / R);
  const arcSegments = 10;
  const positions = [], normals = [];
  const tri = (a, b, c, na, nb = na, nc = na) => {
    // Wind every triangle to face its shading normal.
    const u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    const g = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
    if (g[0] * na[0] + g[1] * na[1] + g[2] * na[2] < 0) { [b, c] = [c, b]; [nb, nc] = [nc, nb]; }
    positions.push(...a, ...b, ...c); normals.push(...na, ...nb, ...nc);
  };
  const quad = (a, b, c, d, na, nb = na, nc = na, nd = na) => { tri(a, b, c, na, nb, nc); tri(a, c, d, na, nc, nd); };
  const rot = (x, y, angle) => [x * Math.cos(angle) - y * Math.sin(angle), x * Math.sin(angle) + y * Math.cos(angle)];
  // Outer boundary of the face, counterclockwise, as [x, y, kind].
  const outline = [];
  const rimArcs = [], mouths = [];
  const slotOutline = [];
  for (let k = 0; k < teeth; k++) {
    const c = k * pitchAngle;
    const along = Math.sqrt(R * R - half * half);
    // Slot k: from its left rim corner (t = +half side is counterclockwise).
    const rightRim = rot(along, -half, c), rightIn = rot(rin, -half, c), leftIn = rot(rin, half, c), leftRim = rot(along, half, c);
    outline.push(rightRim, rightIn, leftIn, leftRim);
    slotOutline.push({ c, rightRim, rightIn, leftIn, leftRim });
    const arc = [];
    const a0 = c + mouthHalfAngle, a1 = c + pitchAngle - mouthHalfAngle;
    for (let i = 1; i < arcSegments; i++) {
      const a = a0 + (a1 - a0) * i / arcSegments;
      const q = [R * Math.cos(a), R * Math.sin(a)];
      outline.push(q); arc.push(q);
    }
    rimArcs.push([leftRim, ...arc]);
    const mouth = [];
    for (let i = 0; i <= 4; i++) {
      const a = c - mouthHalfAngle + 2 * mouthHalfAngle * i / 4;
      mouth.push(i === 0 ? rightRim : i === 4 ? leftRim : [R * Math.cos(a), R * Math.sin(a)]);
    }
    mouths.push(mouth);
  }
  // Close each rim arc onto the next slot's right rim corner.
  rimArcs.forEach((arc, k) => arc.push(slotOutline[(k + 1) % teeth].rightRim));
  const boreSegments = 96;
  const bore = Array.from({ length: boreSegments }, (_, i) => { const a = TAU * i / boreSegments; return [B * Math.cos(a), B * Math.sin(a)]; });
  const v2 = (q) => new THREE.Vector2(q[0], q[1]);
  const planar = (outer, holes, z, up) => {
    const triangles = THREE.ShapeUtils.triangulateShape(outer.map(v2), holes.map(h => h.map(v2)));
    const all = [...outer, ...holes.flat()];
    for (const [i, j, k] of triangles) {
      const a = [...all[i], z], b = [...all[j], z], c = [...all[k], z];
      const cz = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
      if ((cz > 0) === up) tri(a, b, c, [0, 0, up ? 1 : -1]); else tri(a, c, b, [0, 0, up ? 1 : -1]);
    }
  };
  const holeCW = [...bore].reverse();
  // Face (z = 0) and back (z = -T).
  planar(outline, [holeCW], 0, true);
  const backOutline = [];
  for (let k = 0; k < teeth; k++) { backOutline.push(...mouths[k].slice(0, -1)); backOutline.push(...rimArcs[k].slice(0, -1)); }
  planar(backOutline, [holeCW], -T, false);
  // Slot floors, walls and rim.
  for (let k = 0; k < teeth; k++) {
    const { c, rightRim, rightIn, leftIn, leftRim } = slotOutline[k];
    // Floor: rightIn -> leftIn -> leftRim -> along the rim -> rightRim.
    planar([rightIn, leftIn, ...[...mouths[k]].reverse()], [], -D, true);
    const tangent = [-Math.sin(c), Math.cos(c)], radial = [Math.cos(c), Math.sin(c)];
    // Right wall (t = -half) faces +t, left wall faces -t, inner end faces +radial.
    const up = (q, z) => [q[0], q[1], z];
    quad(up(rightIn, -D), up(rightRim, -D), up(rightRim, 0), up(rightIn, 0), [tangent[0], tangent[1], 0]);
    quad(up(leftRim, -D), up(leftIn, -D), up(leftIn, 0), up(leftRim, 0), [-tangent[0], -tangent[1], 0]);
    quad(up(leftIn, -D), up(rightIn, -D), up(rightIn, 0), up(leftIn, 0), [radial[0], radial[1], 0]);
    // Rim under the slot mouth, from the floor down to the back.
    const mouth = mouths[k];
    for (let i = 0; i < mouth.length - 1; i++) {
      const a = mouth[i], b = mouth[i + 1], na = [a[0] / R, a[1] / R, 0], nb = [b[0] / R, b[1] / R, 0];
      quad(up(a, -T), up(b, -T), up(b, -D), up(a, -D), na, nb, nb, na);
    }
    // Full-height rim between slots.
    const arc = rimArcs[k];
    for (let i = 0; i < arc.length - 1; i++) {
      const a = arc[i], b = arc[i + 1], na = [a[0] / R, a[1] / R, 0], nb = [b[0] / R, b[1] / R, 0];
      // Split at the slot-floor depth so the slot corners meet no T-junction.
      quad(up(a, -T), up(b, -T), up(b, -D), up(a, -D), na, nb, nb, na);
      quad(up(a, -D), up(b, -D), up(b, 0), up(a, 0), na, nb, nb, na);
    }
  }
  // Bore.
  for (let i = 0; i < boreSegments; i++) {
    const a = bore[i], b = bore[(i + 1) % boreSegments], na = [-a[0] / B, -a[1] / B, 0], nb = [-b[0] / B, -b[1] / B, 0];
    quad([a[0], a[1], 0], [b[0], b[1], 0], [b[0], b[1], -T], [a[0], a[1], -T], na, nb, nb, na);
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geometry.userData = { profile: 'rectangular-rim-open-face-slots', ...p };
  return geometry;
}

// Crest radius table: rows along theta (thetaStart + i * 2 pi / angularSteps),
// crestSteps + 1 columns across the thread (u from -w/2 to w/2). Missing
// entries mean the full tip radius.
export function crestGridKey195(p = FACE_SLOT_WORM_195) {
  const { thetaStart, count } = crestGrid195(p);
  return [p.angularSteps, p.crestSteps, count, thetaStart.toFixed(12), p.threadWidth, p.wormTipRadius, p.faceOffset, p.clearance, p.crestAllowance].join(':');
}

export function crestRadiusLookup(trim, p = FACE_SLOT_WORM_195) {
  const map = new Map();
  // A crest baked for another grid or design is not applied (the bake itself
  // builds the model before it has written a matching crest).
  if (trim && trim.grid === crestGridKey195(p)) for (const [i, j, r] of trim.entries) map.set(i * (p.crestSteps + 1) + j, r);
  return (i, j) => map.get(i * (p.crestSteps + 1) + j) ?? p.wormTipRadius;
}

export function crestGrid195(p = FACE_SLOT_WORM_195) {
  const P = faceSlotWorm195Pitch(p), lead = p.handedness * P / TAU, L = p.wormTurns * P, w = p.threadWidth;
  const dTheta = TAU / p.angularSteps;
  // Every theta whose helix row (u from -w/2 to P - w/2) meets |z| <= L/2.
  const ends = [-L / 2, L / 2].flatMap(z => [-w / 2, P - w / 2].map(u => (z - u) / lead));
  const thetaStart = Math.floor(Math.min(...ends) / dTheta - 2) * dTheta;
  const thetaEnd = Math.ceil(Math.max(...ends) / dTheta + 2) * dTheta;
  const count = Math.round((thetaEnd - thetaStart) / dTheta);
  return { P, lead, L, w, dTheta, thetaStart, count };
}

// The worm, local frame: axis along +z, single start, z = u + lead * theta
// (lead is negative for the left-handed thread).
export function crestWorm195Geometry(trim, p = FACE_SLOT_WORM_195) {
  const { P, lead, L, w, dTheta, thetaStart, count } = crestGrid195(p);
  const { wormTipRadius: Rt, wormRootRadius: Rr, wormBoreRadius: Rb, crestSteps: nU, rootSteps: nR } = p;
  const top = crestRadiusLookup(trim, p);
  const theta = i => thetaStart + i * dTheta;
  const point = (u, t, r) => [r * Math.cos(t), r * Math.sin(t), u + lead * t];
  const uTop = j => -w / 2 + w * j / nU;
  const uRoot = j => w / 2 + (P - w) * j / nR;
  const tris = [];
  const push = (a, b, c) => tris.push([a, b, c]);
  const norm = (v) => { const l = Math.hypot(...v) || 1; return v.map(x => x / l); };
  // Crest: finite-difference normals of r(u, theta).
  const topPoint = (i, j) => point(uTop(j), theta(i), top(i, j));
  const topNormal = (i, j) => {
    const a = topPoint(Math.max(0, i - 1), j), b = topPoint(Math.min(count, i + 1), j);
    const c = topPoint(i, Math.max(0, j - 1)), d = topPoint(i, Math.min(nU, j + 1));
    const dt = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], du = [d[0] - c[0], d[1] - c[1], d[2] - c[2]];
    let n = [du[1] * dt[2] - du[2] * dt[1], du[2] * dt[0] - du[0] * dt[2], du[0] * dt[1] - du[1] * dt[0]];
    const t = theta(i); if (n[0] * Math.cos(t) + n[1] * Math.sin(t) < 0) n = n.map(x => -x);
    return norm(n);
  };
  const V = (pos, n) => ({ p: pos, n });
  for (let i = 0; i < count; i++) {
    for (let j = 0; j < nU; j++) {
      const a = V(topPoint(i, j), topNormal(i, j)), b = V(topPoint(i + 1, j), topNormal(i + 1, j));
      const c = V(topPoint(i + 1, j + 1), topNormal(i + 1, j + 1)), d = V(topPoint(i, j + 1), topNormal(i, j + 1));
      push(a, b, c); push(a, c, d);
    }
    // Root between threads (a true cylinder).
    for (let j = 0; j < nR; j++) {
      const rn = t => [Math.cos(t), Math.sin(t), 0];
      const a = V(point(uRoot(j), theta(i), Rr), rn(theta(i))), b = V(point(uRoot(j), theta(i + 1), Rr), rn(theta(i + 1)));
      const c = V(point(uRoot(j + 1), theta(i + 1), Rr), rn(theta(i + 1))), d = V(point(uRoot(j + 1), theta(i), Rr), rn(theta(i)));
      push(a, b, c); push(a, c, d);
    }
    // Flanks: helicoids u = +w/2 (facing +z) and u = -w/2 (facing -z).
    for (const side of [1, -1]) {
      const j = side > 0 ? nU : 0, u = side * w / 2;
      // Normal of the helicoid z = u + lead * theta: d/dr x d/dtheta.
      const flankNormal = (t, r) => norm([side * lead * Math.sin(t), -side * lead * Math.cos(t), side * r]);
      const t0 = theta(i), t1 = theta(i + 1), r0 = top(i, j), r1 = top(i + 1, j);
      const a = V(point(u, t0, Rr), flankNormal(t0, Rr)), b = V(point(u, t1, Rr), flankNormal(t1, Rr));
      const c = V(point(u, t1, r1), flankNormal(t1, r1)), d = V(point(u, t0, r0), flankNormal(t0, r0));
      if (side > 0) { push(a, d, c); push(a, c, b); } else { push(a, b, c); push(a, c, d); }
    }
  }
  // Clip every triangle to |z| <= L/2 and collect the cut edges on each plane.
  const key = q => q.map(x => Math.round(x * 1e9)).join(',');
  const cut = (a, b, z) => {
    // Canonical order so a shared edge gives one bit-identical point.
    const [p0, p1] = key(a.p) < key(b.p) ? [a, b] : [b, a];
    const t = (z - p0.p[2]) / (p1.p[2] - p0.p[2]);
    const pos = [p0.p[0] + (p1.p[0] - p0.p[0]) * t, p0.p[1] + (p1.p[1] - p0.p[1]) * t, z];
    return { p: pos, n: norm(p0.n.map((x, k) => x + (p1.n[k] - x) * t)), onPlane: true };
  };
  const clip = (poly, sign) => {
    const z = sign * L / 2, inside = q => sign * q.p[2] <= L / 2 + 1e-12;
    const out = [];
    for (let k = 0; k < poly.length; k++) {
      const a = poly[k], b = poly[(k + 1) % poly.length];
      if (inside(a)) out.push(a);
      if (inside(a) !== inside(b)) out.push(cut(a, b, z));
    }
    return out;
  };
  const positions = [], normals = [];
  const segments = [[], []];
  for (const t of tris) {
    let poly = clip(clip(t, 1), -1);
    if (poly.length < 3) continue;
    {
      // Wind outward (Newell normal against the shading normals).
      let g = [0, 0, 0], n = [0, 0, 0];
      for (let k = 0; k < poly.length; k++) {
        const a = poly[k].p, b = poly[(k + 1) % poly.length].p;
        g = [g[0] + (a[1] - b[1]) * (a[2] + b[2]), g[1] + (a[2] - b[2]) * (a[0] + b[0]), g[2] + (a[0] - b[0]) * (a[1] + b[1])];
        n = n.map((x, d) => x + poly[k].n[d]);
      }
      if (g[0] * n[0] + g[1] * n[1] + g[2] * n[2] < 0) poly = poly.reverse();
    }
    // Drop repeated corners where a vertex lies on the plane.
    poly = poly.filter((v, k) => key(v.p) !== key(poly[(k + 1) % poly.length].p));
    if (poly.length < 3) continue;
    for (let k = 1; k < poly.length - 1; k++) {
      const a = poly[0].p, b = poly[k].p, c = poly[k + 1].p;
      const u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
      if (Math.hypot(u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]) < 1e-14) continue;
      for (const q of [poly[0], poly[k], poly[k + 1]]) { positions.push(...q.p); normals.push(...q.n); }
    }
    for (let k = 0; k < poly.length; k++) {
      const a = poly[k], b = poly[(k + 1) % poly.length];
      for (const [side, z] of [[0, -L / 2], [1, L / 2]]) {
        if (Math.abs(a.p[2] - z) < 1e-12 && Math.abs(b.p[2] - z) < 1e-12 && key(a.p) !== key(b.p)) segments[side].push([a.p, b.p]);
      }
    }
  }
  // End caps: chain the cut edges into the outline, then bore it.
  const boreSegments = 64;
  const bore = Array.from({ length: boreSegments }, (_, i) => { const a = TAU * i / boreSegments; return [Rb * Math.cos(a), Rb * Math.sin(a)]; });
  for (const [side, z] of [[0, -L / 2], [1, L / 2]]) {
    const next = new Map();
    for (const [a, b] of segments[side]) {
      if (next.has(key(a))) throw new Error(`Worm end outline branches at ${key(a)}`);
      next.set(key(a), b);
    }
    const start = segments[side][0][0], loop = [start];
    let cursor = next.get(key(start));
    for (let guard = 0; cursor && key(cursor) !== key(start); guard++) {
      if (guard > 1e6) throw new Error('Worm end outline does not close');
      loop.push(cursor); cursor = next.get(key(cursor));
    }
    if (!cursor) throw new Error('Worm end outline is open');
    const outer = loop.map(q => new THREE.Vector2(q[0], q[1]));
    const hole = bore.map(q => new THREE.Vector2(q[0], q[1]));
    if (THREE.ShapeUtils.isClockWise(outer)) outer.reverse();
    if (!THREE.ShapeUtils.isClockWise(hole)) hole.reverse();
    const all = [...outer, ...hole];
    for (const [i, j, k] of THREE.ShapeUtils.triangulateShape(outer, [hole])) {
      const face = [all[i], all[j], all[k]];
      const cz = (face[1].x - face[0].x) * (face[2].y - face[0].y) - (face[1].y - face[0].y) * (face[2].x - face[0].x);
      const want = side === 1;
      if ((cz > 0) !== want) face.reverse();
      for (const v of face) { positions.push(v.x, v.y, z); normals.push(0, 0, side ? 1 : -1); }
    }
  }
  for (let i = 0; i < boreSegments; i++) {
    const a = bore[i], b = bore[(i + 1) % boreSegments], na = [-a[0] / Rb, -a[1] / Rb, 0], nb = [-b[0] / Rb, -b[1] / Rb, 0];
    const A = [a[0], a[1], -L / 2], B2 = [b[0], b[1], -L / 2], C = [b[0], b[1], L / 2], D2 = [a[0], a[1], L / 2];
    positions.push(...A, ...C, ...B2, ...A, ...D2, ...C); normals.push(...na, ...nb, ...nb, ...na, ...na, ...nb);
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geometry.userData = { profile: 'square-thread-worm-with-slot-generated-crest', length: L, pitch: P, lead, tipRadius: Rt, rootRadius: Rr, boreRadius: Rb, threadWidth: w, trimmed: Boolean(trim) && trim.grid === crestGridKey195(p) };
  return geometry;
}

// Same group structure as makeSolidWorm: root (axis) -> rotor -> thread.
export function makeCrestWorm195(trim, p = FACE_SLOT_WORM_195) {
  const geometry = crestWorm195Geometry(trim, p);
  const thread = new THREE.Mesh(geometry, matte(PALETTE.driver, { metalness: 0.15, roughness: 0.58 }));
  thread.userData.screwThread = true;
  thread.userData.role = 'square-threaded-bored-worm-with-slot-cut-crest';
  const rotor = new THREE.Group();
  rotor.add(thread);
  const root = new THREE.Group();
  root.add(rotor);
  const axis = new THREE.Vector3(1, 0, 0);
  root.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), axis);
  const { P, L, lead } = crestGrid195(p);
  Object.assign(root.userData, {
    axis, rotor, thread, handedness: p.handedness, length: L, pitch: P, lead, radius: p.wormTipRadius, turns: p.wormTurns, starts: 1,
    boreRadius: p.wormBoreRadius, rootRadius: p.wormRootRadius, tipRadius: p.wormTipRadius, threadWidth: p.threadWidth,
    toothProfile: 'square-thread-slot-generated-crest',
  });
  return root;
}
